package com.codepilot1c.core.edt.development;
import org.junit.Test;import static org.junit.Assert.*;import java.util.*;
public class DirectClientTimingTest {
 @Test public void defaultBudgetsAndStartupRemainSeparate(){assertEquals(60,DirectClientTiming.seconds(Map.of()));assertEquals(70,DirectClientTiming.replySeconds(Map.of()));assertEquals(105,DirectClientTiming.replySeconds(Map.of("operation","ready","startup_timeout_ms",90000)));}
 @Test public void callerCanIncreaseTheWholePacketAndReplyBudgets(){assertEquals(90,DirectClientTiming.seconds(Map.of("operation_timeout_s",90.0)));assertEquals(100,DirectClientTiming.replySeconds(Map.of("operation_timeout_s",90)));assertEquals(310,DirectClientTiming.replySeconds(Map.of("operation_timeout_s",300)));DirectClientTiming.validate(Map.of("operation_timeout_s",90,"wait_timeout_ms",60000));}
 @Test public void invalidOrInconsistentBudgetsAreRejected(){for(Object value:List.of(0,4,301,true,5.5,"90")){assertThrows(IllegalArgumentException.class,()->DirectClientTiming.seconds(Map.of("operation_timeout_s",value)));}assertThrows(IllegalArgumentException.class,()->DirectClientTiming.validate(Map.of("wait_timeout_ms",61000)));}
 @Test public void wholeBatchBudgetIsInheritedByStepsBeforeAnyLaunch(){var step=Map.<String,Object>of("action","wait","expected_window","Map","wait_timeout_ms",90000);var a=new LinkedHashMap<String,Object>(Map.of("action","batch","snapshot_id","preflight","expected_window","Map","steps",List.of(step)));assertThrows(IllegalArgumentException.class,()->DirectTestClientService.validateAction(a));a.put("operation_timeout_s",90);DirectTestClientService.validateAction(a);a.put("steps",List.of(Map.of("action","wait","expected_window","Map","operation_timeout_s",90)));assertThrows(IllegalArgumentException.class,()->DirectTestClientService.validateAction(a));}
 @Test public void currentReadinessNeverReusesStartupConnectivity(){var initial=Map.<String,Object>of("ui_ready",true,"transport_state","usable");var out=new LinkedHashMap<String,Object>();DirectTestClientService.effectiveReadiness(out,initial,false);assertEquals(false,out.get("ui_ready"));assertEquals(false,out.get("protocol_connected"));assertEquals("disconnected",out.get("transport_state"));assertEquals(true,out.get("startup_ui_ready"));DirectTestClientService.effectiveReadiness(out,Map.of("ui_ready",true,"last_failure",Map.of("transport_state","broken")),false);assertEquals("broken",out.get("transport_state"));DirectTestClientService.effectiveReadiness(out,initial,true);assertEquals(true,out.get("ui_ready"));assertEquals("usable",out.get("transport_state"));}
}
